#include <stdio.h>
#include <signal.h>
#include <stdlib.h>

void handle_sigint(int sig) {
    printf("\nCaught signal %d (Ctrl + C)\n", sig);
    printf("Cleaning up before exit...Goodbye!\n");
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    while (1) {
        printf("Running... Press Ctrl + C to trigger signal.\n");
        sleep(1);
    }

    return 0;
}
